<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { doAction } from '@/api'
import PageHeader from '@/components/PageHeader.vue'
import HelpTip from '@/components/HelpTip.vue'
import PosterPreview from '@/components/PosterPreview.vue'
import { useModalStore } from '@/stores/modal'

interface CustomWord { id: number; replaced: string; replace: string; front: string; back: string; offset: string; regex: number; season: number; type: number; enabled: number; help: string }
interface WordGroup { id: number; name: string; type: number; seasons: number; link?: string; image?: string; words: CustomWord[] }
interface ImportGroup { id: number; name: string; link?: string; words: CustomWord[] }
const modal = useModalStore()
const groups = ref<WordGroup[]>([])
const loading = ref(false)
const expandedGroups = ref<Set<number>>(new Set())
const selectedIds = ref<Set<string>>(new Set())
const selectedCount = computed(() => selectedIds.value.size)
const wordTypes = [{ value: 1, label: '屏蔽' }, { value: 2, label: '替换' }, { value: 3, label: '替换 + 集偏移' }, { value: 4, label: '集偏移' }]

const editVisible = ref(false); const editTitle = ref('新增识别词'); const editSaving = ref(false)
const form = reactive({ id: '' as string | number, gid: '' as string | number, group_type: 1, new_replaced: '', new_replace: '', new_front: '', new_back: '', new_offset: '', new_help: '', season: -1, type: 1, enabled: 1, regex: 1 })
const groupVisible = ref(false); const groupSaving = ref(false); const groupForm = reactive({ tmdb_id: '', tmdb_type: 'tv' })
const exportNoteVisible = ref(false); const exportNote = ref(''); const exportIdsInfo = ref(''); const exportCodeVisible = ref(false); const exportCode = ref('')
const importCodeVisible = ref(false); const importCode = ref(''); const importAnalysing = ref(false); const importAnalyseVisible = ref(false); const importAnalyseNote = ref(''); const importAnalyseGroups = ref<ImportGroup[]>([]); const importAnalyseSelected = ref<Set<string>>(new Set()); const importSaving = ref(false)

function keyOf(group: WordGroup | ImportGroup, word: CustomWord) { return `${group.id}_${word.id}` }
function toggleGroup(id: number) { const next = new Set(expandedGroups.value); next.has(id) ? next.delete(id) : next.add(id); expandedGroups.value = next }
function toggleSelect(key: string) { const next = new Set(selectedIds.value); next.has(key) ? next.delete(key) : next.add(key); selectedIds.value = next }
function selectGroupAll(group: WordGroup, checked: boolean) { const next = new Set(selectedIds.value); group.words.forEach((word) => checked ? next.add(keyOf(group, word)) : next.delete(keyOf(group, word))); selectedIds.value = next }
function selectImportGroupAll(group: ImportGroup, checked: boolean) { const next = new Set(importAnalyseSelected.value); group.words.forEach((word) => checked ? next.add(keyOf(group, word)) : next.delete(keyOf(group, word))); importAnalyseSelected.value = next }
function toggleImportSelect(key: string) { const next = new Set(importAnalyseSelected.value); next.has(key) ? next.delete(key) : next.add(key); importAnalyseSelected.value = next }
function seasonLabel(season: number) { return season === -1 ? '全部季' : season === -2 ? '' : `第${season}季` }
async function load() { loading.value = true; try { const res = await doAction<{ code: number; msg?: string; result?: WordGroup[] }>('get_customwords', {}); if (res.code === 0) { groups.value = res.result || []; expandedGroups.value = new Set(groups.value.map((group) => group.id)) } else modal.error(res.msg || '获取识别词失败') } catch (error) { modal.error(error instanceof Error ? error.message : '获取识别词失败') } finally { loading.value = false } }
function resetWord(group: WordGroup) { Object.assign(form, { id: '', gid: group.id, group_type: group.type, new_replaced: '', new_replace: '', new_front: '', new_back: '', new_offset: '', new_help: '', season: -1, type: 1, enabled: 1, regex: 1 }); editTitle.value = '新增识别词'; editVisible.value = true }
async function openEdit(word: CustomWord, group: WordGroup) { const res = await doAction<{ code: number; msg?: string; data?: CustomWord }>('get_custom_word', { wid: word.id }); if (res.code === 0 && res.data) { Object.assign(form, { id: word.id, gid: group.id, group_type: group.type, new_replaced: res.data.replaced, new_replace: res.data.replace, new_front: res.data.front, new_back: res.data.back, new_offset: res.data.offset, new_help: res.data.help, season: group.type === 1 ? -1 : res.data.season, type: res.data.type, enabled: res.data.enabled, regex: res.data.regex }); editTitle.value = '编辑识别词'; editVisible.value = true } else modal.error(res.msg || '获取识别词详情失败') }
async function submitWord() { if (form.type === 1 && !form.new_replaced) return modal.warning('请填写被替换词'); if ((form.type === 2 || form.type === 3) && (!form.new_replaced || !form.new_replace)) return modal.warning('请填写被替换词和替换词'); if ((form.type === 3 || form.type === 4) && (!form.new_front || !form.new_back || !form.new_offset)) return modal.warning('请填写定位词和偏移集数'); editSaving.value = true; try { const payload: Record<string, string> = {}; Object.entries(form).forEach(([key, value]) => { payload[key] = String(value) }); const res = await doAction<{ code: number; msg?: string }>('add_or_edit_custom_word', payload); if (res.code === 0) { editVisible.value = false; modal.success('保存成功'); load() } else modal.error(res.msg || '保存失败') } finally { editSaving.value = false } }
async function deleteWord(word: CustomWord) { const ok = await modal.confirm(`确认删除识别词「${word.replaced || word.front}」？`); if (!ok) return; const res = await doAction<{ code: number; msg?: string }>('delete_custom_word', { id: word.id }); if (res.code === 0) { modal.success('删除成功'); load() } else modal.error(res.msg || '删除失败') }
async function deleteGroup(group: WordGroup) { const ok = await modal.confirm('组内识别词将被同步删除，是否确认？'); if (!ok) return; const res = await doAction<{ code: number; msg?: string }>('delete_custom_word_group', { gid: group.id }); if (res.code === 0) { modal.success('删除成功'); load() } else modal.error(res.msg || '删除失败') }
async function batchCheck(flag: 'enable' | 'disable') { if (!selectedCount.value) return modal.warning('请先选择识别词'); const res = await doAction<{ code: number; msg?: string }>('check_custom_words', { flag, ids_info: Array.from(selectedIds.value) }); if (res.code === 0) { selectedIds.value = new Set(); modal.success('操作成功'); load() } else modal.error(res.msg || '操作失败') }
async function addGroup() { if (!groupForm.tmdb_id || isNaN(Number(groupForm.tmdb_id))) return modal.warning('请填写有效的 TMDB ID'); const res = await doAction<{ code: number; msg?: string }>('add_custom_word_group', { ...groupForm }); if (res.code === 0) { groupVisible.value = false; groupForm.tmdb_id = ''; modal.success('新增成功'); load() } else modal.error(res.msg || '新增失败') }
function openExport() { if (!selectedCount.value) return modal.warning('请先选择识别词'); exportIdsInfo.value = Array.from(selectedIds.value).join('@'); exportNote.value = ''; exportNoteVisible.value = true }
async function doExport() { if (!exportNote.value) return modal.warning('请填写分享备注'); const res = await doAction<{ code: number; string?: string; msg?: string }>('export_custom_words', { note: exportNote.value, ids_info: exportIdsInfo.value }); if (res.code === 0) { exportNoteVisible.value = false; exportCode.value = res.string || ''; exportCodeVisible.value = true } else modal.error(res.msg || '导出失败') }
async function copyExport() { try { await navigator.clipboard.writeText(exportCode.value); modal.success('已复制到剪贴板') } catch { modal.error('复制失败') } }
function openImport() { importCode.value = ''; importCodeVisible.value = true }
async function analyseImport() { if (!importCode.value) return modal.warning('请粘贴分享代码'); importAnalysing.value = true; try { const res = await doAction<{ code: number; note_string?: string; groups?: Array<Record<string, unknown>>; msg?: string }>('analyse_import_custom_words_code', { import_code: importCode.value }); if (res.code === 0) { importAnalyseNote.value = res.note_string || ''; importAnalyseGroups.value = (res.groups || []).map((group) => ({ id: Number(group.id), name: String(group.name || ''), link: group.link as string | undefined, words: Array.isArray(group.words) ? group.words as CustomWord[] : Object.values((group.words || {}) as Record<string, CustomWord>) })); importAnalyseSelected.value = new Set(); importCodeVisible.value = false; importAnalyseVisible.value = true } else modal.error(res.msg || '解析失败') } catch (error) { modal.error(error instanceof Error ? error.message : '解析失败') } finally { importAnalysing.value = false } }
async function doImport() { if (!importAnalyseSelected.value.size) return modal.warning('请选择要导入的识别词'); importSaving.value = true; try { const res = await doAction<{ code: number; msg?: string }>('import_custom_words', { import_code: importCode.value, ids_info: Array.from(importAnalyseSelected.value) }); if (res.code === 0) { importAnalyseVisible.value = false; importAnalyseGroups.value = []; importAnalyseSelected.value = new Set(); modal.success('导入成功'); load() } else modal.error(res.msg || '导入失败') } finally { importSaving.value = false } }
onMounted(load)
</script>

<template>
  <div class="customwords"><PageHeader title="自定义识别词" description="屏蔽、替换和集偏移规则管理"><template #actions><q-btn outline icon="refresh" label="刷新" :loading="loading" @click="load" /><q-btn outline color="positive" icon="play_arrow" label="启用" @click="batchCheck('enable')" /><q-btn outline icon="pause" label="停用" @click="batchCheck('disable')" /><q-btn outline icon="download" label="导出" @click="openExport" /><q-btn outline icon="upload" label="导入" @click="openImport" /><q-btn color="primary" unelevated icon="add" label="新增组" @click="groupVisible = true" /></template></PageHeader><q-inner-loading :showing="loading"><q-spinner-dots color="primary" size="40px" /></q-inner-loading>
    <div v-if="!loading && !groups.length" class="empty-state"><q-icon name="text_fields" size="48px" color="grey-5" />未配置任何识别词组</div>
    <q-card v-for="group in groups" :key="group.id" flat bordered class="group-card"><q-card-section class="group-header"><div class="group-title" role="button" tabindex="0" @click="toggleGroup(group.id)" @keydown.enter.prevent="toggleGroup(group.id)"><q-icon :name="expandedGroups.has(group.id) ? 'expand_more' : 'chevron_right'" color="grey-7" /><PosterPreview v-if="group.image" :src="group.image" class="group-poster" /><a v-if="group.link" :href="group.link" target="_blank" rel="noreferrer" class="group-name">{{ group.name }}</a><span v-else class="group-name">{{ group.name }}</span></div><div class="group-actions"><q-btn flat dense color="primary" icon="add" label="新增识别词" @click="resetWord(group)" /><q-btn v-if="group.id !== -1" flat dense color="negative" icon="delete" label="删除组" @click="deleteGroup(group)" /></div></q-card-section><q-slide-transition><q-card-section v-show="expandedGroups.has(group.id)" class="word-section"><div v-if="group.words.length" class="word-list"><div class="word-head"><q-checkbox :model-value="group.words.length > 0 && group.words.every((word) => selectedIds.has(keyOf(group, word)))" @update:model-value="(value) => selectGroupAll(group, value)" /><span>本组 {{ group.words.length }} 条识别词</span></div><div v-for="word in group.words" :key="word.id" class="word-item"><q-checkbox :model-value="selectedIds.has(keyOf(group, word))" @update:model-value="() => toggleSelect(keyOf(group, word))" /><div class="word-main"><div class="word-title"><span>{{ word.replaced || word.front || '集偏移规则' }}</span><q-badge :color="word.enabled === 1 ? 'positive' : 'grey-6'" :label="word.enabled === 1 ? '启用' : '停用'" /><q-badge v-if="word.regex === 1" outline color="primary" label="RegEx" /></div><div class="word-detail"><span v-if="word.replace">替换为：{{ word.replace }}</span><span v-if="word.front || word.back">定位：{{ word.front }} … {{ word.back }}</span><span v-if="word.offset">偏移：{{ word.offset }}</span><q-badge v-if="seasonLabel(word.season)" color="warning" :label="seasonLabel(word.season)" /></div><div v-if="word.help" class="word-help">{{ word.help }}</div></div><div class="word-actions"><q-btn flat round dense color="primary" icon="edit" aria-label="编辑" @click="openEdit(word, group)" /><q-btn flat round dense color="negative" icon="delete" aria-label="删除" @click="deleteWord(word)" /></div></div></div><div v-else class="empty-group"><q-icon name="playlist_add" size="34px" color="grey-5" />没有识别词，请点击“新增识别词”</div></q-card-section></q-slide-transition></q-card>

    <q-dialog v-model="editVisible" :maximized="$q.screen.lt.sm" :full-width="!$q.screen.lt.sm" persistent><q-card class="edit-dialog"><q-card-section class="row items-center no-wrap"><div class="text-h6">{{ editTitle }}</div><q-space /><q-btn flat round dense icon="close" aria-label="关闭" @click="editVisible = false" /></q-card-section><q-separator /><q-form @submit.prevent="submitWord"><q-card-section class="dialog-body"><q-option-group v-model="form.type" :options="wordTypes" color="primary" inline class="type-options" /><div class="form-grid q-mt-md"><q-input v-if="form.type !== 4" v-model="form.new_replaced" outlined dense label="被替换词 *" placeholder="被替换词" /><q-input v-if="form.type === 2 || form.type === 3" v-model="form.new_replace" outlined dense label="替换词 *" placeholder="替换词" /></div><q-banner v-if="form.type === 3 || form.type === 4" dense rounded class="bg-blue-1 text-primary q-mt-md">集偏移规则会在前、后定位词之间提取集数：前定位词填写集数前的内容，后定位词填写集数后的内容；偏移支持 -10、EP+1、2*EP、2*EP-1 等表达式。</q-banner><div v-if="form.type === 3 || form.type === 4" class="form-grid q-mt-md"><q-input v-model="form.new_front" outlined dense label="前定位词（集数前） *" placeholder="如 第" /><q-input v-model="form.new_back" outlined dense label="后定位词（集数后） *" placeholder="如 集" /><q-input v-model="form.new_offset" outlined dense label="偏移集数 *" placeholder="如 -10 或 EP+1"><template #append><HelpTip text="定位词标定集数位置；偏移支持 EP+1、2*EP、2*EP-1 等表达式。" /></template></q-input></div><div class="form-grid q-mt-md"><q-select v-model="form.regex" outlined dense emit-value map-options label="正则表达式" :disable="form.type === 3 || form.type === 4" :options="[{ value: 1, label: '使用' }, { value: 0, label: '不使用' }]" /><q-select v-if="form.group_type === 2" v-model="form.season" outlined dense emit-value map-options label="季" :options="[{ value: -1, label: '全部' }]" /><q-select v-model="form.enabled" outlined dense emit-value map-options label="状态" :options="[{ value: 1, label: '启用' }, { value: 0, label: '停用' }]" /></div><q-input v-model="form.new_help" outlined type="textarea" autogrow label="备注" class="q-mt-md" /></q-card-section><q-separator /><q-card-actions align="right" class="dialog-actions"><q-btn flat label="取消" @click="editVisible = false" /><q-btn color="primary" unelevated :loading="editSaving" label="确定" type="submit" /></q-card-actions></q-form></q-card></q-dialog>
    <q-dialog v-model="groupVisible" :maximized="$q.screen.lt.sm" :full-width="!$q.screen.lt.sm" persistent><q-card class="small-dialog"><q-card-section class="row items-center"><div class="text-h6">新增识别词组</div><q-space /><q-btn flat round dense icon="close" aria-label="关闭" @click="groupVisible = false" /></q-card-section><q-separator /><q-form @submit.prevent="addGroup"><q-card-section class="dialog-body"><q-input v-model="groupForm.tmdb_id" outlined dense label="TMDB ID *" placeholder="TMDB 编号" inputmode="numeric" /><q-select v-model="groupForm.tmdb_type" outlined dense emit-value map-options label="类型" :options="[{ value: 'movie', label: '电影' }, { value: 'tv', label: '电视剧' }]" class="q-mt-md" /></q-card-section><q-separator /><q-card-actions align="right" class="dialog-actions"><q-btn flat label="取消" @click="groupVisible = false" /><q-btn color="primary" unelevated label="确定" :loading="groupSaving" type="submit" /></q-card-actions></q-form></q-card></q-dialog>
    <q-dialog v-model="exportNoteVisible" :maximized="$q.screen.lt.sm" :full-width="!$q.screen.lt.sm" persistent><q-card class="small-dialog"><q-card-section class="row items-center"><div class="text-h6">导出自定义识别词</div><q-space /><q-btn flat round dense icon="close" aria-label="关闭" @click="exportNoteVisible = false" /></q-card-section><q-separator /><q-form @submit.prevent="doExport"><q-card-section class="dialog-body"><q-input v-model="exportNote" outlined type="textarea" autogrow label="分享备注 *" placeholder="应用的资源标题、文件名、站点等"><template #append><HelpTip text="备注会和识别词一起分享给其他用户。" /></template></q-input></q-card-section><q-separator /><q-card-actions align="right" class="dialog-actions"><q-btn flat label="取消" @click="exportNoteVisible = false" /><q-btn color="primary" unelevated label="生成分享代码" type="submit" /></q-card-actions></q-form></q-card></q-dialog>
    <q-dialog v-model="exportCodeVisible" :maximized="$q.screen.lt.sm" :full-width="!$q.screen.lt.sm"><q-card class="small-dialog"><q-card-section class="row items-center"><div class="text-h6">导出自定义识别词</div><q-space /><q-btn flat round dense icon="close" aria-label="关闭" v-close-popup /></q-card-section><q-separator /><q-card-section><pre class="code-box">{{ exportCode }}</pre></q-card-section><q-card-actions align="right"><q-btn outline icon="content_copy" label="复制" @click="copyExport" /><q-btn color="primary" label="关闭" v-close-popup /></q-card-actions></q-card></q-dialog>
    <q-dialog v-model="importCodeVisible" :maximized="$q.screen.lt.sm" :full-width="!$q.screen.lt.sm" persistent><q-card class="small-dialog"><q-card-section class="row items-center"><div class="text-h6">导入自定义识别词</div><q-space /><q-btn flat round dense icon="close" aria-label="关闭" @click="importCodeVisible = false" /></q-card-section><q-separator /><q-card-section class="dialog-body"><q-input v-model="importCode" outlined type="textarea" autogrow label="分享代码" placeholder="粘贴分享的规则内容" /></q-card-section><q-separator /><q-card-actions align="right" class="dialog-actions"><q-btn flat label="取消" @click="importCodeVisible = false" /><q-btn color="primary" unelevated label="解析分享代码" :loading="importAnalysing" @click="analyseImport" /></q-card-actions></q-card></q-dialog>
    <q-dialog v-model="importAnalyseVisible" :maximized="$q.screen.lt.sm" :full-width="!$q.screen.lt.sm" persistent><q-card class="analyse-dialog"><q-card-section class="row items-center no-wrap"><div class="text-h6">导入自定义识别词</div><q-space /><q-btn flat round dense icon="close" aria-label="关闭" @click="importAnalyseVisible = false" /></q-card-section><q-separator /><q-card-section class="dialog-body"><q-banner v-if="importAnalyseNote" rounded class="note-banner"><pre>{{ importAnalyseNote }}</pre></q-banner><div v-for="group in importAnalyseGroups" :key="group.id" class="analyse-group"><div class="analyse-header"><a v-if="group.link" :href="group.link" target="_blank" rel="noreferrer">{{ group.name }}</a><span v-else>{{ group.name }}</span><q-checkbox :model-value="group.words.length > 0 && group.words.every((word) => importAnalyseSelected.has(keyOf(group, word)))" @update:model-value="(value) => selectImportGroupAll(group, value)" /></div><div class="analyse-list"><div v-for="word in group.words" :key="word.id" class="analyse-item"><q-checkbox :model-value="importAnalyseSelected.has(keyOf(group, word))" @update:model-value="() => toggleImportSelect(keyOf(group, word))" /><span class="col">{{ word.replaced || word.front }}</span><span v-if="word.replace" class="text-secondary">→ {{ word.replace }}</span><q-badge v-if="word.offset" color="info" :label="word.offset" /></div></div></div></q-card-section><q-separator /><q-card-actions align="right" class="dialog-actions"><q-btn flat label="取消" @click="importAnalyseVisible = false" /><q-btn color="primary" unelevated label="导入" :loading="importSaving" @click="doImport" /></q-card-actions></q-card></q-dialog>
  </div>
</template>

<style scoped>
.customwords { position: relative; max-width: 1200px; min-width: 0; margin: 0 auto; }.group-card { margin-bottom: 12px; overflow: hidden; border-radius: 14px; background: var(--surface); color: var(--text-primary); }.group-header { display: flex; align-items: flex-start; justify-content: space-between; gap: 10px; min-height: 58px; padding: 10px 16px; }.group-title { display: flex; align-items: center; gap: 8px; min-width: 0; flex: 1; cursor: pointer; user-select: none; }.group-name { min-width: 0; overflow: hidden; color: var(--q-primary); font-weight: 600; text-overflow: ellipsis; white-space: nowrap; }.group-poster { width: 48px; height: 72px; flex: 0 0 auto; border-radius: 4px; }.group-actions, .word-actions { display: flex; flex: 0 0 auto; flex-wrap: wrap; gap: 2px; }.word-section { max-width: 1100px; margin: 0 auto; padding-top: 0; }.word-list { display: flex; flex-direction: column; gap: 6px; }.word-head { display: flex; align-items: center; gap: 8px; color: var(--text-secondary); font-size: 12px; }.word-item { display: flex; align-items: flex-start; gap: 8px; min-width: 0; padding: 9px 10px; border: 1px solid var(--border-subtle); border-radius: 10px; }.word-main { min-width: 0; flex: 1; }.word-title, .word-detail { display: flex; align-items: center; flex-wrap: wrap; gap: 6px; }.word-title { font-size: 14px; font-weight: 600; }.word-detail { margin-top: 5px; color: var(--text-secondary); font-size: 12px; }.word-help { margin-top: 5px; color: var(--text-secondary); font-size: 12px; }.empty-state, .empty-group { display: flex; flex-direction: column; align-items: center; gap: 10px; padding: 52px 0; color: var(--text-secondary); }.edit-dialog, .small-dialog, .analyse-dialog { width: min(600px, calc(100vw - 32px)); max-width: none; border-radius: 16px; background: var(--surface); color: var(--text-primary); }.small-dialog { width: min(560px, calc(100vw - 32px)); }.analyse-dialog { width: min(800px, calc(100vw - 32px)); }.dialog-body { max-height: 68vh; overflow-y: auto; padding: 20px 24px; }.form-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px; }.type-options { gap: 12px; }.code-box, .note-banner pre { max-height: 380px; margin: 0; overflow: auto; padding: 12px; border-radius: 8px; background: var(--surface-muted); color: var(--text-primary); white-space: pre-wrap; word-break: break-all; font: 12px/1.6 Consolas, Monaco, monospace; }.note-banner { margin-bottom: 12px; background: var(--primary-soft); }.analyse-group { margin-bottom: 14px; }.analyse-header { display: flex; align-items: center; justify-content: space-between; font-weight: 600; }.analyse-list { display: flex; flex-direction: column; gap: 4px; margin-top: 5px; }.analyse-item { display: flex; align-items: center; gap: 8px; padding: 4px 8px; border: 1px solid var(--border-subtle); border-radius: 8px; font-size: 13px; }.analyse-item .col { min-width: 0; flex: 1; overflow: hidden; text-overflow: ellipsis; }.text-secondary { color: var(--text-secondary); }.dialog-actions { gap: 8px; padding: 12px 24px 16px; }
@media (max-width: 700px) { .group-header { flex-direction: column; }.group-actions { width: 100%; }.form-grid { grid-template-columns: 1fr; } }
